SELECT C.EXPENSE_ID, C.MBER_ID, C.CATEGORY_ID, C.AMOUNT, C.EXPENSE_NOTE, DATE_FORMAT(C.EXPENSE_DT,'%Y-%m-%d') EXPENSE_DT, EXPENSE_TM, DATE_FORMAT(C.CREAT_DT,'%Y-%m-%d') CREAT_DT, DATE_FORMAT(C.UPDT_DT,'%Y-%m-%d') UPDT_DT, C.CATEGORY_ID, D.CODE_NM CATEGORY_NM, A.USER_NM AS MBER_NM, A.OFFM_TELNO, A.EMAIL_ADRES AEMAIL_ADRES, B.ORGNZT_NM FROM COMTNEXPENSEMANAGE C LEFT OUTER JOIN COMTCCMMNDETAILCODE D ON D.CODE_ID ='COM087' AND C.CATEGORY_ID = D.CODE LEFT OUTER JOIN COMTNEMPLYRINFO A ON A.ESNTL_ID= C.MBER_ID LEFT OUTER JOIN COMTNORGNZTINFO B ON A.ORGNZT_ID = B.ORGNZT_ID WHERE C.MBER_ID = #{uniqId}
AND D.CODE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND C.EXPENSE_NOTE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY D.CODE_NM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) totcnt FROM COMTNEXPENSEMANAGE C LEFT OUTER JOIN COMTCCMMNDETAILCODE D ON D.CODE_ID ='COM087' AND C.CATEGORY_ID = D.CODE LEFT OUTER JOIN COMTNEMPLYRINFO A ON A.ESNTL_ID= C.MBER_ID LEFT OUTER JOIN COMTNORGNZTINFO B ON A.ORGNZT_ID = B.ORGNZT_ID WHERE C.MBER_ID = #{uniqId}
AND D.CODE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND C.EXPENSE_NOTE LIKE CONCAT('%', #{searchKeyword}, '%')

